sp_widget.client_script:
api.controller = function ($rootScope, $window) {
    var c = this;

    c.saving = false;
    c.filtering = false;
    c.serverErrors = [];

    c.modal = {
        open: false,
        row: null,
        state: '',
        closeNotes: ''
    };

    c.isActiveFilter = function (value) {
        return (c.data.categoryFilter || '') === (value || '');
    };

    // Category filter is applied by the server query, not only in the DOM
    c.setFilter = function (value) {
        if (c.filtering || c.isActiveFilter(value)) {
            return;
        }
        c.filtering = true;
        c.data.action = 'filter_queue';
        c.data.categoryFilter = value || '';

        c.server.update().then(function () {
            c.filtering = false;
            c.data.action = null;
        });
    };

    // ---------------- Inline manage / resolve modal ----------------
    c.openModal = function (row) {
        c.serverErrors = [];
        c.modal = {
            open: true,
            row: row,
            state: row.stateValue,
            closeNotes: row.close_notes || ''
        };
    };

    c.closeModal = function () {
        c.modal.open = false;
        c.modal.row = null;
    };

    c.isModalValid = function () {
        if (!c.modal.state) {
            return false;
        }
        // Resolution notes are mandatory when closing the grievance as complete
        if (c.modal.state === '3' && !(c.modal.closeNotes || '').trim()) {
            return false;
        }
        return true;
    };

    c.saveModal = function () {
        if (!c.isModalValid()) {
            return;
        }

        c.saving = true;
        c.serverErrors = [];

        // Assign onto c.data BEFORE c.server.update()
        c.data.action = 'save_grievance';
        c.data.recordSysId = c.modal.row.sys_id;
        c.data.recordState = c.modal.state;
        c.data.recordCloseNotes = c.modal.closeNotes;

        c.server.update().then(function () {
            c.saving = false;
            c.data.action = null;

            var result = c.data.saveResult;
            if (result && result.success) {
                // c.data.rows was rebuilt by the server script, so the queue is
                // already refreshed in place.
                c.closeModal();

                // Broadcast for any sibling widget that chooses to listen.
                // The installed Grievance SLA Dashboard does NOT subscribe to this,
                // so c.data.kpiStale drives a visible reload prompt instead of
                // pretending the KPI tiles refreshed.
                $rootScope.$broadcast('x_1850267_public_0.grievance.updated', {
                    number: result.number,
                    closed: !!result.closed
                });
                $rootScope.$broadcast('sp.widget.refresh');
            } else if (result && result.errors) {
                c.serverErrors = result.errors;
            } else {
                c.serverErrors = ['The grievance could not be updated. Please try again.'];
            }
        });
    };

    c.dismissKpiPrompt = function () {
        c.data.kpiStale = false;
    };

    c.reloadPage = function () {
        $window.location.reload();
    };
};

sp_widget.css:
.grievance-agent-queue {
    .panel-title {
        font-size: $font-size-large;
        margin: 0;
    }

    .grievance-error-list {
        margin: 0;
        padding-left: 18px;
    }

    .grievance-kpi-prompt {
        .grievance-kpi-reload {
            margin-left: 8px;
        }
    }

    .grievance-filter-bar {
        margin-bottom: 14px;

        .grievance-filter-status {
            margin-left: 10px;
            font-size: $font-size-small;
        }
    }

    .grievance-queue-table {
        font-size: $font-size-small;

        th {
            white-space: nowrap;
        }

        .grievance-cell-number {
            font-weight: 600;
            white-space: nowrap;
        }

        .label {
            font-size: $font-size-small;
            white-space: nowrap;
        }
    }

    .grievance-hash-inline {
        font-family: $font-family-monospace;
        font-size: $font-size-small;
        cursor: help;
        background-color: transparent;
        color: $text-muted;
        padding: 0;
    }

    .grievance-empty {
        padding: 18px 0;
    }

    .grievance-asof {
        margin: 8px 0 0;
        font-size: $font-size-small;
        text-align: right;
    }

    /* ---------- Inline manage / resolve modal ----------
       Bootstrap 3 hides .modal by default and relies on its JS plugin to set
       display. This widget drives the modal with ng-if instead, so the extra
       class raises specificity to show it without using !important. */
    .modal.grievance-modal {
        display: block;
        overflow-x: hidden;
        overflow-y: auto;

        .modal-title {
            font-size: $font-size-large;
        }

        .grievance-modal-facts {
            margin-bottom: 16px;

            dt {
                font-size: $font-size-small;
                text-transform: uppercase;
                letter-spacing: 0.04em;
                color: $text-muted;
            }

            dd {
                margin-bottom: 10px;
                word-break: break-word;
            }
        }

        .grievance-modal-notes {
            resize: vertical;
        }
    }
}

sp_widget.script:
(function () {
    var TABLE = 'x_1850267_public_0_grievance';

    var CATEGORY_FILTERS = [
        { label: 'All', value: '' },
        { label: 'Water', value: 'water' },
        { label: 'Electricity', value: 'electricity' },
        { label: 'Sanitation', value: 'sanitation' },
        { label: 'Roads', value: 'roads' }
    ];

    // States an agent may set from the inline manage modal
    var STATE_CHOICES = [
        { label: 'Open', value: '1' },
        { label: 'Work in Progress', value: '2' },
        { label: 'Closed Complete', value: '3' }
    ];

    // Distinct Bootstrap 3 label class per state value
    var STATE_CLASS_MAP = {
        '1': 'label-info',
        '2': 'label-warning',
        '3': 'label-success',
        '4': 'label-danger',
        '7': 'label-default',
        '-5': 'label-default'
    };

    var CLOSED_COMPLETE = '3';
    var ESCALATION_OVERDUE = '3';
    var HASH_PREVIEW_LENGTH = 12;

    // Initialise every data.* property so the template never binds to undefined
    data.categoryFilters = CATEGORY_FILTERS;
    data.stateChoices = STATE_CHOICES;
    data.rows = [];
    data.categoryFilter = '';
    data.rowLimit = 50;
    data.asOf = '';
    data.saveResult = null;
    data.kpiStale = false;

    var action = input && input.action ? input.action + '' : '';

    if (action === 'filter_queue') {
        data.categoryFilter = normaliseCategory(input && input.categoryFilter);
    } else if (action === 'save_grievance') {
        data.categoryFilter = normaliseCategory(input && input.categoryFilter);
        data.saveResult = saveGrievance(input);
        // Any successful state/active change moves the sibling KPI dashboard numbers
        data.kpiStale = !!data.saveResult.success;
    }

    data.rows = loadQueue(data.categoryFilter);
    data.asOf = new GlideDateTime().getDisplayValue();

    // ------------------------------------------------------------------
    // Queue
    // ------------------------------------------------------------------
    function loadQueue(category) {
        var rows = [];

        // "now" for SLA comparison - new GlideDateTime() is the scoped-safe
        // equivalent of gs.nowDateTime().
        var now = new GlideDateTime();

        var gr = new GlideRecordSecure(TABLE);
        gr.addQuery('active', true);
        if (category) {
            gr.addQuery('grievance_category', category);
        }
        // Ascending target resolution: the most urgent / already breached first
        gr.orderBy('target_resolution');
        gr.setLimit(50);
        gr.query();

        while (gr.next()) {
            var stateValue = gr.getValue('state') + '';
            var escalationValue = gr.getValue('escalation') + '';
            var targetValue = gr.getValue('target_resolution') || '';
            var hash = gr.getValue('cryptographic_hash') || '';

            var overdueByDate = false;
            if (targetValue) {
                var target = new GlideDateTime(targetValue);
                overdueByDate = target.compareTo(now) < 0;
            }

            var overdue = overdueByDate || escalationValue === ESCALATION_OVERDUE;

            rows.push({
                sys_id: gr.getUniqueValue() + '',
                number: gr.getValue('number') || '',
                citizen_name: gr.getValue('citizen_name') || '',
                category: gr.getDisplayValue('grievance_category') || '',
                short_description: gr.getValue('short_description') || '',
                state: gr.getDisplayValue('state') || '',
                stateValue: stateValue,
                stateClass: STATE_CLASS_MAP[stateValue] || 'label-default',
                target_resolution: gr.getDisplayValue('target_resolution') || '',
                close_notes: gr.getValue('close_notes') || '',
                escalation: gr.getDisplayValue('escalation') || '',
                slaLabel: overdue ? 'OVERDUE' : 'ON TRACK',
                slaClass: overdue ? 'label-danger' : 'label-success',
                hash_full: hash,
                hash_short: hash ? hash.substring(0, HASH_PREVIEW_LENGTH) + '...' : ''
            });
        }

        return rows;
    }

    // ------------------------------------------------------------------
    // Inline manage / resolve save handler
    // ------------------------------------------------------------------
    function saveGrievance(payload) {
        var sysId = trim(payload.recordSysId);
        var state = trim(payload.recordState);
        var closeNotes = trim(payload.recordCloseNotes);

        var errors = [];

        if (!sysId) {
            errors.push('No grievance was selected.');
        }

        if (!isValidState(state)) {
            errors.push('Select a valid state.');
        }

        if (state === CLOSED_COMPLETE && !closeNotes) {
            errors.push('Resolution notes are required when closing a grievance as complete.');
        }

        if (errors.length > 0) {
            return { success: false, errors: errors };
        }

        var gr = new GlideRecordSecure(TABLE);
        gr.addQuery('sys_id', sysId);
        gr.setLimit(1);
        gr.query();

        if (!gr.next()) {
            return {
                success: false,
                errors: ['Grievance not found, or you do not have permission to update it.']
            };
        }

        gr.setValue('state', state);

        if (closeNotes) {
            gr.setValue('close_notes', closeNotes.substring(0, 4000));
        }

        if (state === CLOSED_COMPLETE) {
            // active -> false is what fires the "Grievance Resolved Notification"
            // (it triggers on activeCHANGESTOfalse).
            gr.setValue('active', false);
        }

        var number = gr.getValue('number') || '';

        if (!gr.update()) {
            return {
                success: false,
                errors: ['The grievance could not be updated. You may not have write access to it.']
            };
        }

        return {
            success: true,
            number: number,
            closed: state === CLOSED_COMPLETE
        };
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------
    function trim(value) {
        if (value === null || value === undefined) {
            return '';
        }
        return (value + '').trim();
    }

    function normaliseCategory(value) {
        var candidate = trim(value);
        for (var i = 0; i < CATEGORY_FILTERS.length; i++) {
            if (CATEGORY_FILTERS[i].value === candidate) {
                return candidate;
            }
        }
        return '';
    }

    function isValidState(value) {
        for (var i = 0; i < STATE_CHOICES.length; i++) {
            if (STATE_CHOICES[i].value === value) {
                return true;
            }
        }
        return false;
    }
})();
